class Order {
    private final double total;
    private final OrderStatus status;
    private final int statusCode;

    public Order(double total, OrderStatus status) {
        this.total = total;
        this.status = status;
        this.statusCode = mapStatusToLegacyCode(status);
    }

    private static int mapStatusToLegacyCode(OrderStatus status) {
        switch (status) {
            case PENDING: return 0;
            case CONFIRMED: return 1;
            case CANCELLED: return 2;
            default: return -1;
        }
    }

    public double getTotal() {
        return total;
    }

    public int getStatusCode() {
        return statusCode;
    }

    public OrderStatus getStatus() {
        return status;
    }
}

