#include <iostream>

enum class OrderStatus {
    Pending = 0,
    Confirmed = 1,
    Cancelled = 2
};

class Order {
public:
    Order(double total, OrderStatus status)
        : total_(total), status_(status), statusCode_(static_cast<int>(status)) {}

    double getTotal() const { return total_; }
    int getStatusCode() const { return statusCode_; }
    OrderStatus getStatus() const { return status_; }

private:
    double total_;
    OrderStatus status_;
    int statusCode_;
};

class NamingExample {
public:
    static constexpr double FREE_SHIPPING_THRESHOLD = 50.0;

    // Weak: leaks implementation detail, unclear intent, magic number
    bool check(const Order& o, int x) const {
        return o.getTotal() > x && o.getStatusCode() == 1;
    }

    // Strong: name states intent, no magic numbers, status is a real type
    bool isEligibleForFreeShipping(const Order& order) const {
        return order.getTotal() > FREE_SHIPPING_THRESHOLD
            && order.getStatus() == OrderStatus::Confirmed;
    }
};

int main() {
    Order order(75.0, OrderStatus::Confirmed);
    NamingExample rules;

    std::cout << std::boolalpha;
    std::cout << "Weak check(order, 50): " << rules.check(order, 50) << std::endl;
    std::cout << "Strong isEligibleForFreeShipping(order): " << rules.isEligibleForFreeShipping(order) << std::endl;

    return 0;
}
